let setupEmail=null;
const scopeNames={all:'Toàn hệ thống',iid:'Cấp IID',department:'Bộ phận được giao',personal:'Cá nhân được giao'},opNames={initialize:'Khởi tạo kho KPI',replace:'Nhập toàn bộ dữ liệu',kpi:'Cập nhật định nghĩa KPI',delete:'Lưu trữ KPI',restore:'Khôi phục KPI',update:'Cập nhật kết quả tháng',mix:'Đổi cơ cấu trọng số',review:'Đánh giá quý',action:'Cập nhật công việc',delete_action:'Xóa công việc',member:'Cập nhật tài khoản',login:'Đăng nhập',password_setup:'Thiết lập mật khẩu QT',password_change:'Đổi mật khẩu',password_reset:'Cấp lại mật khẩu tạm'};
function totalScore(ks,p){if(!ks.length)return null;return user.role==='admin'?KPI.composite(state,ks,p):state.scopeScores?.[p.type+'|'+p.value+'|'+KPI.key(ks[0])]??null;}
function ownScore(ks,p){if(!ks.length)return null;return user.role==='admin'?KPI.weighted(ks,p):state.ownScores?.[p.type+'|'+p.value+'|'+KPI.key(ks[0])]??KPI.weighted(ks,p);}
function applyMenus(){document.querySelectorAll('nav button').forEach(b=>{b.hidden=!user||b.dataset.view==='members'&&user.role!=='admin'||user.mustChange&&b.dataset.view!=='account';b.classList.toggle('active',b.dataset.view===view)});$('#import').parentElement.hidden=!user||user.role!=='admin';$('#backup').hidden=!user||user.mustChange;$('#logout').hidden=!user;$('.avatar').textContent=user?`${user.name||user.email.split('@')[0]} · ${roleNames[user.role]}`:'Khách';}
function logoutUI(){user=null;state=null;version=0;stale=false;view='overview';document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.body.classList.add('signedout');applyMenus();}
function renderLogin(){logoutUI();$('#app').innerHTML=`<div class="loginbox"><div class="eyebrow">IID · KPI WORKSPACE 2027</div><h1>${setupEmail?'Thiết lập mật khẩu quản trị':'Đăng nhập tài khoản KPI'}</h1><p>${setupEmail?'Xác thực quản trị hiện có đã hoàn tất. Hãy tự đặt mật khẩu để dùng tài khoản email/mật khẩu.':'Sử dụng email và mật khẩu được quản trị cấp.'}</p><form id="loginform"><label>Email<input name="email" type="email" autocomplete="username" required value="${esc(setupEmail||'')}" ${setupEmail?'readonly':''}></label><label>${setupEmail?'Mật khẩu mới':'Mật khẩu'}<input name="password" type="password" autocomplete="${setupEmail?'new-password':'current-password'}" required ${setupEmail?'minlength="15"':''}></label>${setupEmail?'<label>Nhập lại mật khẩu mới<input name="confirm" type="password" autocomplete="new-password" required></label><p class="mini">Ít nhất 15 ký tự; tối đa 72 byte UTF-8.</p>':''}<p id="loginerror" role="alert"></p><button class="primary">${setupEmail?'Thiết lập & đăng nhập':'Đăng nhập'}</button></form>${setupEmail?'<p><button onclick="setupEmail=null;renderLogin()">Dùng tài khoản đã có mật khẩu</button></p>':'<p class="mini">Quên mật khẩu? Liên hệ quản trị để cấp lại mật khẩu tạm.</p><a class="mini" href="/signin-with-chatgpt?return_to=%2F" target="_top">Thiết lập mật khẩu lần đầu cho quản trị hiện có</a>'}</div>`;$('#loginform').onsubmit=async e=>{e.preventDefault();let f=e.target,b=f.querySelector('button');if(setupEmail&&f.elements.password.value!==f.elements.confirm.value){$('#loginerror').textContent='Hai mật khẩu chưa khớp.';return}b.disabled=true;try{let x=await req(setupEmail?'/auth/setup':'/auth/login','POST',{email:f.elements.email.value,password:f.elements.password.value});setupEmail=null;user=x.user;await enterWorkspace()}catch(e){$('#loginerror').textContent=e.message}finally{b.disabled=false}};}
async function enterWorkspace(){document.body.classList.remove('signedout');applyMenus();if(user.mustChange){view='account';render();return}let x=await req('/api/workspace');state=x.state?KPI.migrate(x.state):null;version=x.version;view='overview';render();}
function renderAccount(){if(!user)return renderLogin();$('#app').innerHTML=head('Tài khoản & mật khẩu','Tự quản lý mật khẩu và bảo mật phiên đăng nhập cho tài khoản của bạn.')+`<div class="panel"><h2>${esc(user.name)}</h2><p>${esc(user.email)} · <span class="badge">${esc(roleNames[user.role])}</span><br>Phạm vi dữ liệu: <strong>${esc(scopeNames[user.scope_level])}</strong>${user.team?' · Bộ phận: <strong>'+esc(user.team)+'</strong>':''}</p>${user.mustChange?'<div class="alert">Bạn đang dùng mật khẩu tạm. Hãy đổi mật khẩu trước khi xem hoặc cập nhật KPI.</div>':''}<form id="passwordform" class="fields"><label>Mật khẩu hiện tại<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>Mật khẩu mới<input name="newPassword" type="password" minlength="15" autocomplete="new-password" required></label><label>Nhập lại mật khẩu mới<input name="confirm" type="password" autocomplete="new-password" required></label><button class="primary">Đổi mật khẩu</button></form><p class="mini">Ít nhất 15 ký tự, tối đa 72 byte UTF-8. Tất cả phiên đăng nhập trước sẽ tự động bị thu hồi khi đổi mật khẩu.</p></div>`;$('#passwordform').onsubmit=async e=>{e.preventDefault();let f=e.target;if(f.elements.newPassword.value!==f.elements.confirm.value)return toast('Hai mật khẩu mới chưa khớp.');let b=f.querySelector('button');b.disabled=true;try{let x=await req('/auth/change-password','POST',{currentPassword:f.elements.currentPassword.value,newPassword:f.elements.newPassword.value});user=x.user;await enterWorkspace();toast('Đã đổi mật khẩu và thu hồi các phiên cũ.')}catch(e){toast(e.message)}finally{b.disabled=false}};}
function showTemporary(email,p){let d=document.createElement('dialog');d.className='temporary';d.innerHTML=`<h2>Mật khẩu tạm đã khởi tạo</h2><p>Tài khoản <strong>${esc(email)}</strong>. Mật khẩu tạm này chỉ hiển thị một lần. Hãy sao chép và gửi riêng cho nhân sự; họ bắt buộc phải đổi mật khẩu ngay lần đăng nhập đầu tiên.</p><input readonly aria-label="Mật khẩu tạm" value="${esc(p)}"><div class="flexbetween" style="margin-top:16px"><button type="button" id="copytemp">📋 Sao chép mật khẩu</button><button class="primary" id="closetemp">Đã ghi nhận</button></div>`;document.body.appendChild(d);d.querySelector('#copytemp').onclick=()=>{navigator.clipboard?.writeText(p);toast('Đã sao chép mật khẩu tạm')};d.querySelector('#closetemp').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal();}
function renderMembers(){if(user?.role!=='admin'){$('#app').innerHTML=head('Thành viên & quyền','Vai trò hiện tại: '+roleNames[user?.role])+'<div class="panel">Liên hệ quản trị viên để điều chỉnh quyền truy cập.</div>';return}$('#app').innerHTML=head('Tài khoản & phạm vi','Quản trị cấp tài khoản email/mật khẩu và phân quyền phạm vi dữ liệu cho từng thành viên.')+`<form id="memberform" class="panel fields"><label>Email<input name="email" type="email" required placeholder="ten@congty.com"></label><label>Họ tên hiển thị<input name="name" required placeholder="Nguyễn Văn A"></label><label>Vai trò<select name="role"><option value="contributor">Cá nhân (Nhân viên)</option><option value="manager">Quản lý bộ phận</option><option value="leader">Cấp IID</option><option value="viewer">Chỉ xem</option><option value="admin">Quản trị</option></select></label><label>Bộ phận<input name="team" placeholder="VD: Kinh doanh, Vận hành"></label><label>Cấp được xem (cho vai trò Chỉ xem)<select name="scope_level"><option value="personal">Cá nhân theo email tài khoản</option><option value="department">Bộ phận được giao</option><option value="iid">Cấp IID</option></select></label><label class="check"><input name="disabled" type="checkbox"> Khóa tài khoản (thu hồi phiên)</label><button class="primary">Cấp tài khoản / lưu quyền</button></form><p class="mini">Tài khoản mới được tạo mật khẩu tạm tự động (24 ký tự). Với tài khoản đã tồn tại, dùng nút <em>Cấp lại mật khẩu</em> khi cần đặt lại. KPI cá nhân được ánh xạ tự động theo đúng email tài khoản.</p><div id="memberlist" class="sectionspace">Đang tải…</div><div id="auditlist" class="sectionspace"></div>`;$('#memberform').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));data.disabled=e.target.elements.disabled.checked;try{let x=await req('/api/members','POST',data);await loadAccountList();if(x.temporaryPassword)showTemporary(x.email,x.temporaryPassword);else toast('Đã lưu quyền; các phiên đăng nhập cũ của tài khoản này đã được thu hồi.');if(data.email.toLowerCase()===user.email){setupEmail=null;renderLogin()}}catch(e){toast(e.message)}};loadAccountList();}
let accountList=[];
function formatAuditDetails(l){try{let d=JSON.parse(l.details||'{}');let parts=[];if(d.email)parts.push('Tài khoản: '+d.email);if(d.role)parts.push('Vai trò: '+(roleNames[d.role]||d.role));if(d.id)parts.push('ID: '+d.id);if(d.month)parts.push('Tháng '+d.month);if(d.quarter)parts.push('Quý '+d.quarter);return parts.join(' · ')||'—'}catch{return '—'}}
async function loadAccountList(){try{let [ms,logs]=await Promise.all([req('/api/members'),req('/api/audit')]);if(view!=='members')return;accountList=ms;$('#memberlist').innerHTML=`<div class="tablewrap"><table><thead><tr><th>TÀI KHOẢN</th><th>VAI TRÒ / PHẠM VI</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody>${ms.map((m,i)=>`<tr><td><strong>${esc(m.name)}</strong><small>${esc(m.email)}</small></td><td><span class="badge neutral">${esc(roleNames[m.role])}</span><small>${esc(scopeNames[m.scope_level])}${m.team?' · '+esc(m.team):''}</small></td><td><span class="badge ${m.disabled?'bad':m.passwordReady?m.mustChange?'warn':'':'warn'}">${m.disabled?'Đã khóa':m.passwordReady?m.mustChange?'Cần đổi MK tạm':'Đang hoạt động':'Chưa đặt mật khẩu'}</span></td><td><button onclick="editMember(${i})">Sửa quyền</button>${m.email!==user.email?` <button onclick="resetMember(${i})">Cấp lại mật khẩu</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;$('#auditlist').innerHTML='<div class="paneltitle" style="margin-top:28px"><h2>Nhật ký kiểm toán (Audit Log)</h2><small>100 thao tác gần nhất trên hệ thống</small></div><div class="tablewrap"><table><thead><tr><th>THỜI GIAN</th><th>NGƯỜI THỰC HIỆN</th><th>THAO TÁC</th><th>CHI TIẾT</th></tr></thead><tbody>'+logs.map(l=>`<tr><td>${esc(new Date(l.at).toLocaleString('vi-VN'))}</td><td><strong>${esc(l.actor)}</strong></td><td><span class="badge neutral">${esc(opNames[l.operation]||l.operation)}</span></td><td><small style="margin:0">${esc(formatAuditDetails(l))}</small></td></tr>`).join('')+'</tbody></table></div>'}catch(e){toast(e.message)}}
function editMember(i){let m=accountList[i],f=$('#memberform');for(let n of ['email','name','role','team'])f.elements[n].value=m[n]||'';f.elements.scope_level.value=['iid','department','personal'].includes(m.scope_level)?m.scope_level:'personal';f.elements.disabled.checked=m.disabled;f.elements.email.focus();window.scrollTo({top:0,behavior:'smooth'});}
async function resetMember(i){let m=accountList[i];if(!confirm('Cấp lại mật khẩu tạm cho '+m.email+' và thu hồi các phiên đăng nhập cũ?'))return;try{let x=await req('/auth/reset-password','POST',{email:m.email});await loadAccountList();showTemporary(x.email,x.temporaryPassword)}catch(e){toast(e.message)}}
const renderScopedCascade=renderCascadeView;
$('#logout').onclick=async()=>{try{await req('/auth/logout','POST',{});setupEmail=null;renderLogin()}catch(e){toast(e.message)}};
periodOptions();(async()=>{try{let x=await req('/auth/me');setupEmail=x.setupEmail;user=x.user;if(user)await enterWorkspace();else renderLogin()}catch(e){logoutUI();$('#app').innerHTML='<div class="panel"><h1>Kết nối tài khoản</h1><p>'+esc(e.message)+'</p><button onclick="location.reload()">Thử lại</button></div>'}})();
